CREATE TABLE people (id INT PRIMARY KEY, first_name VARCHAR(50) NOT NULL, last_name VARCHAR(50) NOT NULL, full_name VARCHAR(101) AS (CONCAT(first_name, ' ', last_name)) VIRTUAL, name_len INT AS (CHAR_LENGTH(first_name)) PERSISTENT, doc JSON, age INT, secret INT INVISIBLE, KEY idx_full (full_name), KEY idx_age (age) IGNORED, CONSTRAINT chk_age CHECK (age >= 0), CONSTRAINT chk_names CHECK (first_name <> last_name))
